<template>
  <div class="space-y-6">
    <PageHeader :title="user?.displayName || '用户详情'" parent="用户"><template #actions><router-link to="/users" class="ios-btn-secondary">返回用户</router-link><router-link :to="`/devices?userId=${userId}`" class="ios-btn-primary">管理设备</router-link><router-link to="/subscriptions" class="ios-btn-secondary">管理订阅</router-link></template></PageHeader>
    <ErrorState v-if="error" :message="error" @retry="load" /><LoadingSkeleton v-else-if="!user" />
    <template v-else><section class="panel-card p-6"><div class="flex items-center gap-3"><StatusBadge :status="user.status" /><span class="font-semibold text-base text-ios-label">{{ user.username }}</span><span v-if="user.overLimit" class="rounded-full bg-rose-50 border border-rose-200 px-2 py-0.5 text-xs font-medium text-ios-red">连接超限</span></div><dl class="grid grid-cols-2 gap-5 mt-6 text-sm"><div><dt class="text-xs font-medium text-ios-tertiary">到期</dt><dd class="text-sm font-medium text-ios-label mt-1">{{ user.expiresAt ? formatTime(user.expiresAt) : '不过期' }}</dd></div><div><dt class="text-xs font-medium text-ios-tertiary">设备 / 连接上限</dt><dd class="text-sm font-medium text-ios-label mt-1">{{ user.devicesCount }} / {{ user.maxDevices }} 台 · {{ user.maxConnections }} 连接</dd></div><div><dt class="text-xs font-medium text-ios-tertiary">当前连接</dt><dd class="text-sm font-medium text-ios-label mt-1"><template v-if="user.onlineConnections === null"><span class="text-ios-tertiary font-normal">未知</span></template><template v-else><span class="font-mono tabular-nums">{{ user.onlineConnections }} / {{ user.maxConnections }}</span><span v-if="user.overLimit" class="ml-1 font-medium text-ios-red">超限</span></template></dd></div><div><dt class="text-xs font-medium text-ios-tertiary">允许协议</dt><dd class="text-sm font-medium text-ios-label mt-1">{{ user.allowedProtocols.join('、') }}</dd></div><div><dt class="text-xs font-medium text-ios-tertiary">已用流量</dt><dd class="text-sm font-medium text-ios-label mt-1"><TrafficValue :bytes="user.usedTraffic" /><span v-if="user.trafficLimit" class="text-xs text-ios-tertiary ml-2 font-mono tabular-nums">/ {{ (user.trafficLimit / 1073741824).toFixed(1) }} GiB</span></dd><ResourceProgress v-if="user.trafficLimit" :percentage="quotaPercent(user)" :show-label="false" class="mt-2 max-w-[200px]" /><span v-if="user.trafficLimit && user.usedTraffic >= user.trafficLimit" class="text-xs text-ios-red font-medium block mt-1">额度已用尽。节点访问限制在自动配置成功应用后生效。</span><p v-if="singBoxQuota" class="text-xs text-ios-tertiary mt-1">sing-box 节点只上报节点总量，配额仅统计 Xray 节点流量</p></div><div><dt class="text-xs font-medium text-ios-tertiary">授权节点组</dt><dd class="text-sm font-medium text-ios-label mt-1">{{ user.nodeGroupIds.map(id => groups.find(group => group.id === id)?.name || id).join('、') || '未授权' }}</dd></div><div><dt class="text-xs font-medium text-ios-tertiary">备注</dt><dd class="text-sm font-normal text-ios-secondary mt-1">{{ user.remark || '—' }}</dd></div></dl></section>
      <section class="panel-card p-6"><h2 class="font-semibold text-base text-ios-label mb-4">设备</h2><p v-if="!devices.length" class="text-ios-tertiary text-sm">尚未创建设备</p><div v-for="device in devices" :key="device.id" class="py-3 border-b border-black/[0.06] last:border-0"><div class="flex justify-between items-center"><span class="font-semibold text-[15px] text-ios-label">{{ device.name }}</span><StatusBadge :status="device.status" /></div><p class="text-xs text-ios-tertiary mt-1">{{ device.credentials.filter(item => item.status === 'active').map(item => item.protocol).join('、') }} · {{ formatTime(device.lastOnlineAt) }}</p></div></section>
    </template>
  </div>
</template>
<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, watch } from 'vue'; import { useRoute } from 'vue-router'; import { userAPI, type ProxyUser, type ProxyDevice } from '../api'; import { groupAPI, type NodeGroup } from '../../nodes/groupsApi'; import { formatTime } from '../../../app/auth'; import PageHeader from '../../../components/PageHeader.vue'; import StatusBadge from '../../../components/StatusBadge.vue'; import TrafficValue from '../../../components/TrafficValue.vue'; import ResourceProgress from '../../../components/ResourceProgress.vue'; import ErrorState from '../../../components/ErrorState.vue'; import LoadingSkeleton from '../../../components/LoadingSkeleton.vue';
import { request, type Page } from '../../../app/apiClient'; import { choices } from '../../proxy/api'; import type { NodeView } from '../../nodes/api';
const route = useRoute(); const userId = computed(() => String(route.params.id)); const user = ref<ProxyUser | null>(null); const devices = ref<ProxyDevice[]>([]); const groups = ref<NodeGroup[]>([]); const nodes = ref<NodeView[]>([]); const error = ref('');
function quotaPercent(account: ProxyUser) { return account.trafficLimit ? Math.min(100, (account.usedTraffic / account.trafficLimit) * 100) : 0; }
const singBoxQuota = computed(() => { const granted = new Set(groups.value.filter(group => user.value?.nodeGroupIds.includes(group.id)).flatMap(group => group.nodeIds)); return nodes.value.some(node => granted.has(node.id) && node.capabilities?.core_name === 'sing-box'); });
async function load() { try { const [u, d, g, n] = await Promise.all([userAPI.get(userId.value), userAPI.devices(userId.value, 1, 100), groupAPI.list(1, 100), choices((page, size) => request<Page<NodeView>>(`/nodes?page=${page}&pageSize=${size}`))]); user.value = u; devices.value = d.items; groups.value=g.items;nodes.value=n;error.value = ''; } catch (e) { user.value = null; error.value = (e as Error).message; } }
watch(userId, load); onMounted(() => { load(); window.addEventListener('proxy-system-alert', load); }); onUnmounted(() => window.removeEventListener('proxy-system-alert', load));
</script>
